DO $patch$ DECLARE body text; anchor text; BEGIN SELECT pg_get_functiondef('public.pm_gantt_contract_value(uuid)'::regprocedure) INTO body; anchor:='THEN coalesce('; IF strpos(body,anchor)=0 THEN RAISE EXCEPTION 'Contract reference anchor missing'; END IF; body:=replace(body,anchor,'THEN coalesce((SELECT (x->>''budget'')::numeric FROM pm_projects p JOIN quote_contract_references r ON r.quote_id=p.quote_id CROSS JOIN LATERAL jsonb_array_elements(r.stages) x WHERE p.id=s.project_id AND x->>''id''=s.source_quote_stage_id::text LIMIT 1),'); EXECUTE body; SELECT pg_get_functiondef('public.pm_gantt_commercial_read(uuid)'::regprocedure) INTO body; anchor:='SELECT coalesce((SELECT CASE WHEN count(*)=1 THEN min(total_fee) END FROM pm_project_contract_baseline WHERE project_id=_project)'; IF strpos(body,anchor)=0 THEN RAISE EXCEPTION 'Contract total anchor missing'; END IF; body:=replace(body,anchor,'SELECT coalesce((SELECT r.total FROM quote_contract_references r JOIN pm_projects p ON p.quote_id=r.quote_id WHERE p.id=_project), (SELECT CASE WHEN count(*)=1 THEN min(total_fee) END FROM pm_project_contract_baseline WHERE project_id=_project)'); EXECUTE body; END $patch$;